#pragma once
// RemoveUselessChecks: the original handler sub_10044BD0 writes a per-build list
// of game RVAs as NOP / one-byte patches. The data is the ASI's own five RVA
// tables plus its 23 singles (src/useless_checks_data.inc, generated by
// tools/extract_useless_checks.py); this header declares the write shapes and
// the application points the current schedule uses.

#include <cstddef>
#include <cstdint>

#include "common.h"

// One single write: `length` bytes of `byte` at game base + rva.
struct UselessCheckSingle
{
	std::uint32_t rva;
	std::uint8_t length;
	std::uint8_t byte;
};

// The original handler, applied at the two points the port currently uses: the
// RVA tables first thing in PatchGame, the singles after
// RemoveStaticCutsceneCarShadows. Both write only on builds 5 (v1040), 8 (v1070)
// and 9 (v1080); every other build writes nothing. The caller owns the
// RemoveUselessChecks INI gate, exactly like the other arms.
void ApplyUselessCheckTables(GameBuild build, GameImage image);
void ApplyUselessCheckSingles(GameBuild build, GameImage image);
